    const choices=['nod','groom','stretch',...(pet.dataset.kind==='bird'?['flutter',...Object.keys(birdTricks)]:[])].filter(x=>x!==lastIdle);
    lastIdle=choices[Math.floor(Math.random()*choices.length)];play(lastIdle);
